describe('listing sessions', () => {
  const loggedErrors = captureErrors();

  it('answers list_sessions with session_list for the session user and forwards limit and before', async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const sessionStore = {
      listFor: (userId: string | number, options?: SessionListOptions) => {
        seen.push({userId, options});
        return [
          {
            sessionId: 's2',
            createdAt: new Date('2026-01-01T00:00:00.000Z'),
            updatedAt: new Date('2026-01-01T00:02:00.000Z'),
            entryCount: 3,
          },
        ];
      },
    } as unknown as SessionStore;
    const before: SessionCursor = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};

    const sent = await sendListFrame({type: 'list_sessions', limit: 10, before, userId: 'other'}, sessionStore);

    expect({seen, sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 10, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 3,
            },
          ],
        },
      ],
    });
  });

  it('answers an empty session_list when sessionStore or listFor is absent', async () => {
    const withoutStore = await sendListFrame({type: 'list_sessions'});
    const withoutList = await sendListFrame({type: 'list_sessions'}, {} as SessionStore);

    expect({withoutStore, withoutList}).toEqual({
      withoutStore: [{type: 'session_list', sessions: []}],
      withoutList: [{type: 'session_list', sessions: []}],
    });
  });

  it('logs under ws with userId and error and answers SERVER_ERROR when listFor fails', async () => {
    const rejectingStore = {
      listFor: () => Promise.reject(new Error('database offline')),
    } as unknown as SessionStore;
    const throwingStore = {
      listFor: () => {
        throw new Error('sync failure');
      },
    } as unknown as SessionStore;

    const fromRejection = await sendListFrame({type: 'list_sessions'}, rejectingStore);
    const fromThrow = await sendListFrame({type: 'list_sessions'}, throwingStore);

    expect({fromRejection, fromThrow, loggedErrors}).toEqual({
      fromRejection: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
      fromThrow: [{type: 'error', code: 'SERVER_ERROR', message: expect.any(String)}],
      loggedErrors: [
        {category: 'ws', message: expect.any(String), userId: 'u1', error: 'database offline'},
        {category: 'ws', message: expect.any(String), userId: 'u1', error: 'sync failure'},
      ],
    });
  });
});

async function sendListFrame(raw: unknown, sessionStore?: SessionStore): Promise<OutgoingMessage[]> {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (payload: string) => void sent.push(JSON.parse(payload) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = {processMessageStream: jest.fn()} as unknown as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  await createMessageHandler(orchestrator, sessionStore)(ws, session, raw);
  return sent;
}

async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore?: SessionStore
): Promise<void> {
  try {
    const summaries =
      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    const frames: SessionSummaryFrame[] = summaries.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: summary.createdAt.toISOString(),
      updatedAt: summary.updatedAt.toISOString(),
      entryCount: summary.entryCount,
    }));
    sendSessionList(ws, frames);
  } catch (error) {
    const reason = error instanceof Error ? error.message : String(error);
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: reason});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

